// Partner activity widgets. One configured snippet is the template: the city is
// a URL parameter, so every destination is a configuration entry rather than a
// new trip to the partner dashboard. content/experiences.json is generated by
// scripts/sync-experiences.mjs, which keeps only cities that carry at least
// minProducts bookable programs.
//
// One city per page: the picker navigates instead of loading 42 widgets at
// once. The widget runs in the page rather than a sandboxed frame, because it
// loads its own nested frame and crashes with an opaque origin. The page policy
// is widened only on this route, and only to the hosts the configuration names.
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const invalid = reason => { throw new TypeError(`Invalid experience configuration: ${reason}`); };

export const WIDGET_HOSTS = ['tpscr.com', 'tp.media', 'wegotrip.com', 'tpo.gg', 'www.travelpayouts.com'];
const WIDGET_PARAMS = ['promo_id', 'campaign_id', 'powered_by', 'tours', 'show_more', 'locale', 'shmarker', 'trs', 'currency', 'city_id'];
const HOST_KINDS = ['script', 'img', 'frame', 'connect'];
// The brief: at least twenty bookable programs visible per city.
export const MIN_TOURS = 20;
// Equirectangular, cropped north and south of anywhere we sell. These numbers
// are also baked into assets/world.svg; change one and you change both.
export const MAP = { north: 78, south: -58, width: 1000 };
MAP.height = round(MAP.width * (MAP.north - MAP.south) / 360);
function round(value) { return Math.round(value * 10) / 10; }

function origin(value) {
  let url;
  try { url = new URL(value); } catch { invalid(`${value} is not an absolute URL`); }
  if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash || url.pathname !== '/') invalid(`${value} must be a bare https origin`);
  if (!WIDGET_HOSTS.includes(url.hostname)) invalid(`${url.hostname} is not an allowed widget host`);
  return url.origin;
}

export function validateWidget(widget) {
  if (!widget || typeof widget.src !== 'string' || widget.src.length > 1000) invalid('widget.src is required');
  let url;
  try { url = new URL(widget.src); } catch { invalid('widget.src must be an absolute URL'); }
  if (url.protocol !== 'https:' || url.username || url.password || url.hash || !WIDGET_HOSTS.includes(url.hostname)) invalid('widget.src must be https and on an allowed host');
  for (const name of url.searchParams.keys()) if (!WIDGET_PARAMS.includes(name)) invalid(`widget parameter ${name} is not allowed`);
  if (url.searchParams.has('city_id')) invalid('widget.src is a template: the city comes from each entry');
  // The partner attribution badge is a referral feature, not a requirement.
  if (url.searchParams.get('powered_by') !== 'false') invalid('widget.src must set powered_by=false');
  const tours = Number(url.searchParams.get('tours'));
  if (!Number.isInteger(tours) || tours < MIN_TOURS || tours > 40) invalid(`widget.src must request tours=${MIN_TOURS}..40`);
  const hosts = {};
  for (const kind of HOST_KINDS) {
    const list = widget.hosts?.[kind];
    if (!Array.isArray(list) || !list.length || list.length > 6) invalid(`widget.hosts.${kind} needs 1–6 origins`);
    hosts[kind] = list.map(origin);
  }
  if (Object.keys(widget.hosts ?? {}).some(kind => !HOST_KINDS.includes(kind))) invalid('widget.hosts has an unknown kind');
  return { src: url.href, hosts, tours };
}

const generated = {
  hu: (title, country) => `${title}, ${country}. Foglalható belépők, séták és vezetett programok, időpontos jegyekkel.`,
  en: (title, country) => `${title}, ${country}. Bookable tickets, walks and guided activities with timed entry.`,
};

export function validateExperiences(data) {
  if (!data || data.version !== 2 || !Array.isArray(data.cities) || !data.cities.length || data.cities.length > 500) invalid('version 2 and 1–500 cities are required');
  if (!Number.isInteger(data.minProducts) || data.minProducts < MIN_TOURS) invalid(`minProducts must be at least ${MIN_TOURS}`);
  const widget = validateWidget(data.widget);
  if (!data.countries || typeof data.countries !== 'object' || Array.isArray(data.countries)) invalid('countries must be a name map');
  const countries = {};
  for (const [key, value] of Object.entries(data.countries)) {
    if (typeof value !== 'string' || !value.trim() || value.length > 60) invalid(`country ${key} needs a localized name`);
    countries[key] = value.trim();
  }
  const seen = new Set();
  const cities = data.cities.map(city => {
    if (!city || typeof city.slug !== 'string' || !/^[a-z0-9-]{2,60}$/.test(city.slug) || seen.has(city.slug)) invalid('each city needs a unique kebab-case slug');
    if (typeof city.cityId !== 'string' || !/^[1-9][0-9]{3,9}$/.test(city.cityId)) invalid(`city ${city.slug} needs a numeric cityId`);
    if (typeof city.name !== 'string' || !city.name.trim() || city.name.length > 80) invalid(`city ${city.slug} needs a name`);
    if (!Object.hasOwn(countries, city.country)) invalid(`city ${city.slug} names an unlisted country`);
    if (!Number.isInteger(city.products) || city.products < data.minProducts) invalid(`city ${city.slug} must carry at least ${data.minProducts} products`);
    for (const axis of ['lat', 'lon']) {
      const limit = axis === 'lat' ? 90 : 180;
      if (typeof city[axis] !== 'number' || !Number.isFinite(city[axis]) || Math.abs(city[axis]) > limit) invalid(`city ${city.slug} needs a numeric ${axis}`);
    }
    if (city.lat > MAP.north || city.lat < MAP.south) invalid(`city ${city.slug} falls outside the map`);
    if (city.hu !== undefined && (typeof city.hu !== 'string' || !city.hu.trim() || city.hu.length > 80)) invalid(`city ${city.slug} has an unusable Hungarian name`);
    if (city.top !== undefined && (!Array.isArray(city.top) || !city.top.length || city.top.length > 8
      || city.top.some(title => typeof title !== 'string' || title.trim().length < 3 || title.length > 120))) invalid(`city ${city.slug} has unusable sample titles`);
    seen.add(city.slug);
    const title = { hu: (city.hu ?? city.name).trim(), en: city.name.trim() };
    const intro = {};
    for (const lang of ['hu', 'en']) {
      const note = city.notes?.[lang];
      if (note !== undefined && (typeof note !== 'string' || note.trim().length < 40 || note.length > 400)) invalid(`city ${city.slug} has a ${lang} note outside 40–400 characters`);
      intro[lang] = note?.trim() ?? generated[lang](title[lang], lang === 'hu' ? countries[city.country] : city.country);
    }
    const url = new URL(widget.src);
    url.searchParams.set('city_id', city.cityId);
    const samples = (city.top ?? []).map(sample => sample.trim());
    // A page with no text of its own beyond the generated line stays out of the index.
    return { slug: city.slug, cityId: city.cityId, country: city.country, products: city.products, src: url.href, title, intro, samples,
      x: round((city.lon + 180) / 360 * MAP.width), y: round((MAP.north - city.lat) / 360 * MAP.width),
      indexable: Boolean(city.notes || samples.length) };
  });
  return { widget, countries, cities, generated: typeof data.generated === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.generated) ? data.generated : '' };
}

// Only these directives change, and only on this route.
export function widgetPolicy(widget) {
  return {
    scriptExtra: widget.hosts.script.map(host => ` ${host}`).join(''),
    imgExtra: widget.hosts.img.map(host => ` ${host}`).join(''),
    frameSrc: widget.hosts.frame.join(' '),
    connectExtra: widget.hosts.connect,
  };
}

const copy = {
  hu: {
    eye: 'ÉLMÉNYEK / FOGLALHATÓ PROGRAMOK', heading: 'Mi legyen<br><em>az úticél?</em>', citySuffix: 'foglalható programok.',
    map: 'Világtérkép a városokkal. Vidd a kurzort egy pont fölé a város nevéért, és kattints a programjaiért.',
    intro: count => `Belépők, séták és vezetett programok ${count} városban, városonként legalább ${MIN_TOURS} ajánlattal. Válassz várost, és csak annak a kínálata jelenik meg.`,
    source: 'A programlistákat partnerünk állítja össze és frissíti; a kínálat nem teljes, és tételesen nem ellenőrizzük. A listák angol nyelvűek, az árak euróban értendők. A foglalás és a fizetés a szolgáltató oldalán történik.',
    picker: count => `Városválasztó — ${count} város`, featured: 'A legnagyobb választék',
    samples: 'A listán például', asOf: date => `A példák a ${date}-i állapotot tükrözik; az aktuális kínálat alább látható.`,
    affiliate: 'Partneri programlista. A rajta keresztüli foglalás után jutalékot kaphatunk; ez nem befolyásolja, mit írunk.',
    fallback: 'A programlisták betöltéséhez JavaScript szükséges. A városválasztó nélküle is működik.',
    all: 'Összes város', guides: 'Utazási útmutatók', lastMinute: 'Last minute jegyárak',
  },
  en: {
    eye: 'EXPERIENCES / BOOKABLE THINGS TO DO', heading: 'Where are<br><em>you headed?</em>', citySuffix: 'bookable activities.',
    map: 'World map of the cities. Hover a dot for the city name, click it for that city’s activities.',
    intro: count => `Tickets, walks and guided activities in ${count} cities, with at least ${MIN_TOURS} options in each. Pick a city and only its selection is shown.`,
    source: 'These lists are compiled and updated by our partner; the selection is not exhaustive and we do not verify it item by item. Prices are shown in euro. Booking and payment take place on the provider’s website.',
    picker: count => `City picker — ${count} cities`, featured: 'The widest selection',
    samples: 'The list includes, for example', asOf: date => `These examples reflect ${date}; the current selection is shown below.`,
    affiliate: 'Partner activity list. We may earn a commission on bookings made through it; it does not influence what we write.',
    fallback: 'The activity lists require JavaScript. The city picker works without it.',
    all: 'All cities', guides: 'Travel guides', lastMinute: 'Last-minute fares',
  },
};

// Dots on a shared backdrop. No script and no map library: an SVG <title> is
// the browser's own tooltip, and an SVG <a> is an ordinary link.
function worldMap({ countries, cities }, lang, slug) {
  const order = [...cities].sort((a, b) => Number(a.slug === slug) - Number(b.slug === slug));
  const label = city => `${city.title[lang]} — ${lang === 'hu' ? countries[city.country] : city.country}`;
  return `<figure class="city-map"><svg viewBox="0 0 ${MAP.width} ${MAP.height}" role="group" aria-label="${copy[lang].map}"><image href="/assets/world.svg" x="0" y="0" width="${MAP.width}" height="${MAP.height}"></image>${order.map(city => `<a href="/${lang}/experiences/${city.slug}/"${city.slug === slug ? ' aria-current="page"' : ''}><title>${escape(label(city))}</title><circle cx="${city.x}" cy="${city.y}" r="3"></circle></a>`).join('')}</svg><figcaption>${copy[lang].map}</figcaption></figure>`;
}

function picker({ countries, cities }, lang, slug) {
  const groups = new Map();
  for (const city of cities) {
    if (!groups.has(city.country)) groups.set(city.country, []);
    groups.get(city.country).push(city);
  }
  const label = country => lang === 'hu' ? countries[country] : country;
  const sorted = [...groups].sort((a, b) => label(a[0]).localeCompare(label(b[0]), lang));
  return `<details class="city-picker"${slug ? '' : ' open'}><summary>${copy[lang].picker(cities.length)}</summary><div class="city-picker-grid">${sorted.map(([country, list]) => `<section><h2>${escape(label(country))}</h2><ul>${list.map(city => `<li><a href="/${lang}/experiences/${city.slug}/"${city.slug === slug ? ' aria-current="page"' : ''}>${escape(city.title[lang])}</a></li>`).join('')}</ul></section>`).join('')}</div></details>`;
}

function block(city, lang, heading, generated) {
  const text = copy[lang];
  const samples = city.samples?.length
    ? `<p class="experiences-samples">${text.samples}: ${city.samples.map(escape).join(' · ')}.${generated ? ` <span>${text.asOf(generated)}</span>` : ''}</p>`
    : '';
  return `<section class="experiences-block" aria-labelledby="experience-${city.slug}"><h2 id="experience-${city.slug}">${heading}</h2>${samples}<div class="experiences-widget"><script async src="${escape(city.src)}" charset="utf-8"></script></div><small class="experiences-disclosure">${text.affiliate}</small></section>`;
}

export function experiencesPage(data, lang = 'hu', slug = '') {
  const language = lang === 'en' ? 'en' : 'hu', text = copy[language];
  const { cities } = data;
  if (!Array.isArray(cities) || !cities.length) invalid('at least one city is required to render the page');
  const city = slug ? cities.find(entry => entry.slug === slug) : null;
  if (slug && !city) invalid(`unknown city ${slug}`);
  const featured = city ?? cities[0];
  const hero = city
    ? `<h1>${escape(city.title[language])}<br><em>${text.citySuffix}</em></h1>`
    : `<h1>${text.heading}</h1>`;
  return `<div id="trip-experiences" class="flights-page container"><section class="flights-hero"><div><p class="flights-eyebrow">${text.eye}</p>${hero}</div><div><p>${city ? escape(city.intro[language]) : text.intro(cities.length)}</p><small>${text.source}</small></div></section>${worldMap(data, language, slug)}${picker(data, language, slug)}${block(featured, language, city ? escape(city.title[language]) : `${text.featured}: ${escape(featured.title[language])}`, data.generated)}<p class="flights-more">${slug ? `<a href="/${language}/experiences/">${text.all} ↗</a> · ` : ''}<a href="/${language}/last-minute/">${text.lastMinute} ↗</a> · <a href="/${language}/blog/">${text.guides} ↗</a></p><noscript><p>${text.fallback}</p></noscript></div>`;
}
